import{_ as t,o,a as e,b as i}from"./app.UgfkfLuP.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"原子操作","link":"/api/SIMD-API/tensor_api/atomic/atomic"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/atomic/atomic.md","filePath":"api/SIMD-API/tensor_api/atomic/atomic.md","lastUpdated":1793173587000}'),r={name:"api/SIMD-API/tensor_api/atomic/atomic.md"};function m(s,a,l,_,c,n){return o(),e("div",null,[...a[0]||(a[0]=[i('<div><article class="markdown-body"><h1>原子操作</h1><p>DMA（Direct Memory Access，直接内存访问单元）原子操作用于在数据搬运过程中对Global Memory上的已有数据执行原子读改写，再写入搬运结果。Tensor API提供以下接口配置后续目的地址为Global Memory的受支持搬运指令：</p><ul><li><strong><a href="set_atomic_add.html">set_atomic_add</a></strong>：将待搬运数据与Global Memory上的已有数据求和，并将结果写入Global Memory。</li><li><strong><a href="set_atomic_max.html">set_atomic_max</a></strong>：比较待搬运数据与Global Memory上的已有数据，将两者中的最大值写入Global Memory。</li><li><strong><a href="set_atomic_min.html">set_atomic_min</a></strong>：比较待搬运数据与Global Memory上的已有数据，将两者中的最小值写入Global Memory。</li><li><strong><a href="disable_dma_atomic.html">disable_dma_atomic</a></strong>：关闭DMA原子模式，避免原子配置影响后续搬运。</li></ul><p><code>set_atomic_add</code>、<code>set_atomic_max</code>和<code>set_atomic_min</code>通过模板参数指定参与原子操作的数据类型。</p></article></div>',1)])])}const I=t(r,[["render",m]]);export{p as __pageData,I as default};
